def skill():
    s = sqrt(52 + 4*12)
    d = sqrt(52 - 4*12)
    c = (s + d) / 2
    a = (s - d) / 4
    return a + c

def _good():
    a, c = symbols('a c', positive=True)
    sols = solve([Eq(a*c, 12), Eq(c**2 + 4*a**2, 52)], [a, c], dict=True)
    return [s[a] + s[c] for s in sols if 2*s[c] >= 10]

def standard():
    return _good()[0]

def unique():
    return sorted(set(_good()))
